{
  "technical_and_design_decisions": [
    "Implement in Go as an extension of the existing Hyperledger Fabric channel configuration package (e.g., github.com/hyperledger/fabric/common/config).",
    "Use existing Fabric protobuf definitions (common.Config, common.ConfigUpdate, config.Orderer, etc.) for configuration manipulation.",
    "Functions will accept an existing *common.Config or block and return a modified config or a *common.ConfigUpdateEnvelope ready for signing, following the existing config delta pattern.",
    "Certificate validation for U4 will use Go's crypto/x509 to parse and verify KeyUsageCertSign and IsCA attributes; no full chain validation required.",
    "Revocation (U3) will append the certificate DER/PEM to the FabricMSPConfig.revocation_list field for the specified MSP.",
    "Helper retrieval functions (U7, U8) will navigate the config tree and return typed protobuf messages to avoid manual parsing by users.",
    "Examples for U5/U6 will be written as runnable GoDoc examples (package-level example functions) that also serve as tests, using an in-memory crypto identity to sign.",
    "No new external dependencies will be introduced; rely on Fabric's existing config and crypto utilities."
  ],
  "assumptions": [
    "The developer has access to the existing Hyperledger Fabric Go source code and a working build/test environment; no environment setup time is required beyond familiarization.",
    "The target Fabric version is v1.4 as indicated by the tutorial link; APIs are compatible with that version.",
    "Basic config update envelope creation and signing utilities already exist in the Fabric library and will be reused; we only add the specific modifications and helpers.",
    "Unit tests will use synthetic but valid configuration blocks; no integration with a live Fabric network is required.",
    "The 'example test' mentioned in U7/U8 refers to the GoDoc example tests, and they will be updated as part of documentation activities.",
    "Effort estimates exclude ongoing maintenance, CI pipeline changes, and release management."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Requirements analysis and API design",
      "activity_description": "Review Fabric channel config structures, tutorial, and design function signatures for anchor peer add/remove, cert revocation, CA add, and retrieval helpers. Produce a design consistent with existing config package.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Implement add anchor peer (U1)",
      "activity_description": "Develop function to parse existing config block/transaction, add an anchor peer to the specified org's configuration, and compute a ConfigUpdate transaction ready for signature. Include unit tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Implement remove anchor peer (U2)",
      "activity_description": "Develop function to remove an anchor peer from the org configuration and produce ConfigUpdate envelope. Include unit tests.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Implement certificate revocation in MSP config (U3)",
      "activity_description": "Develop function that takes config and cert, locates the MSP, and appends cert to revocation_list of FabricMSPConfig, producing ConfigUpdate. Include unit tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Implement add root CA certificate to MSP (U4)",
      "activity_description": "Develop function to add a CA certificate to MSP config with minimal validation (reject if missing KeyUsageCertSign/CA). Produce ConfigUpdate. Include unit tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Implement retrieve anchor peers helper (U7)",
      "activity_description": "Develop helper function that returns existing anchor peers for a given org from config without manual parsing. Include unit tests.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Implement retrieve orderer configuration helper (U8)",
      "activity_description": "Develop helper to retrieve *config.Orderer from channel config and ensure UpdateOrdererConfiguration can apply modifications. Include unit tests.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Write GoDoc example for config updates and signing (U5)",
      "activity_description": "Create package-level GoDoc example demonstrating idiomatic usage to perform multiple config changes and sign the envelope.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Write GoDoc example for channel create transaction (U6)",
      "activity_description": "Create package-level GoDoc example demonstrating creation and signing of a new channel create transaction.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Update example tests for new helpers (U7/U8)",
      "activity_description": "Modify existing example tests to demonstrate usage of anchor peer and orderer config retrieval helpers as per acceptance criteria.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Integration testing, review, and documentation finalization",
      "activity_description": "Run full test suite, perform self code review, refactor, and ensure all GoDoc examples compile and pass.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 72
  }
}

